def fallback_parse_yaml(text):
    """Basic YAML parser for scalars and inline lists."""
    data = {}
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#") or ":" not in line:
            continue
        key, val = [x.strip() for x in line.split(":", 1)]
        if val.startswith("[") and val.endswith("]"):
            data[key] = [i.strip().strip("'\"") for i in val[1:-1].split(",")]
        elif val.lower() == "true":
            data[key] = True
        elif val.lower() == "false":
            data[key] = False
        elif val.replace(".", "", 1).isdigit():
            data[key] = float(val) if "." in val else int(val)
        else:
            data[key] = val.strip("'\"")
    return data


FRONTMATTER_RE = re.compile(r"\A﻿?---[ \t]*\r?\n(.*?)\r?\n---[ \t]*(?:\r?\n|\Z)", re.DOTALL)
COMMENT_RE = re.compile(r"%%(.*?)%%", re.DOTALL)
WIKILINK_RE = re.compile(r"!?\[\[([^\]\|#]*)(#[^\]\|]*)?(?:\\?\|[^\]]*)?\]\]")
HEADING_RE = re.compile(r"^(#{1,6})\s+(.+?)\s*#*\s*$", re.MULTILINE)
CALLOUT_LINK_RE = re.compile(r"\[\[Meta/Callouts#([^\]\|]+)")
CODE_FENCE_RE = re.compile(r"^```.*?^```", re.MULTILINE | re.DOTALL)
KEYLIKE_RE = re.compile(r"[A-Za-z][A-Za-z0-9_\-]*")
LEDGER_FILE_RE = re.compile(r"Ledger (\d+)\.(\d{4})\.md$")
LEDGER_TITLE_RE = re.compile(r"Lore Ledger (\d+)\.(\d{2})$")


def looks_like_key(value):
    """A short token like `start_desc`, `ff2` or `publisher` rather than real text."""
    if not isinstance(value, str):
        return False
    v = value.strip("'\" ")
    if not KEYLIKE_RE.fullmatch(v):
        return False
    return "_" in v or any(c.isdigit() for c in v) or v.islower()

# =============================================================================
#  Allowed values, read from Meta/Metadata.md
# =============================================================================
def load_allowed_values(content_root, report):
    allowed = {k: set(v) for k, v in FALLBACK_ALLOWED.items()}
    tags = set()
    path = content_root / METADATA_DOC_REL
    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        report.add("read-error", METADATA_DOC_REL, "Couldn't read Meta/Metadata.md; using built-in lists and skipping the tag check.")
        return allowed, None

    def accepts(line_key):
        m = re.search(rf"^\s*{line_key}:.*?Accepts:?(.*)$", text, re.MULTILINE)
        return set(re.findall(r"`([^`]+)`", m.group(1))) if m else None

    for key, line_key in (("type", "type"), ("scope", "scope"), ("progress", "progress"), ("future", "future"),
                          ("has", "has"), ("sort_method", r"method"), ):
        found = accepts(line_key)
        if found:
            allowed[key] = found
    # Sort method and subheader method share the key name `method`.
    for m in re.finditer(r"^\s*method:.*?Accepts:?(.*)$", text, re.MULTILINE):
        values = set(re.findall(r"`([^`]+)`", m.group(1)))
        if "first_character" in values or "value" in values:
            allowed["subheader_method"] = values
        elif values:
            allowed["sort_method"] = values

    for m in re.finditer(r"^[ \t]*-[ \t]*((?:topic|subject)/[^\s#]+)", text, re.MULTILINE):
        tags.add(m.group(1).strip())
    if not tags:
        report.add("read-error", METADATA_DOC_REL, "Found no tags in Meta/Metadata.md; skipping the tag check.")
        return allowed, None
    return allowed, tags

# =============================================================================
#  Report
# =============================================================================
class Report:
    def __init__(self):
        self.items = []  # (severity, code, src, message, line)
        self._seen = set()

    def add(self, code, src, message, line=None):
        severity = SEVERITY_OVERRIDES.get(code, CHECKS[code][0])
        if severity == "off":
            return
        key = (code, src, message)
        if key in self._seen:
            return
        self._seen.add(key)
        self.items.append((severity, code, src, message, line))

    def counts(self):
        c = {s: 0 for s in SEVERITY_ORDER}
        for sev, *_ in self.items:
            c[sev] += 1
        return c

    def render(self, include_notices=True):
        counts = self.counts()
        out = ["# Metadata Aggregator Report", ""]
        if not self.items:
            out.append("_No issues found._")
            return "\n".join(out) + "\n"
        out.append(f"**{counts['error']} errors, {counts['warning']} warnings, {counts['notice']} notices.**")
        out.append("")
        for sev in SEVERITY_ORDER:
            if sev == "notice" and not include_notices:
                continue
            items = [i for i in self.items if i[0] == sev]
            if not items:
                continue
            out.append(f"## {sev.capitalize()}s ({len(items)})")
            by_file = defaultdict(list)
            for _, code, src, msg, line in items:
                by_file[src].append((code, msg, line))
            for src in sorted(by_file):
                out.append(f"### {src}")
                for code, msg, line in sorted(by_file[src], key=lambda x: (x[0], x[1])):
                    where = f" (line {line})" if line else ""
                    out.append(f"- `{code}`{where}: {msg}")
            out.append("")
        used = sorted({i[1] for i in self.items})
        out.append("## Checks")
        out.append("Change a check's level in SEVERITY_OVERRIDES at the top of metadata_aggregator.py.")
        for code in used:
            out.append(f"- `{code}` ({SEVERITY_OVERRIDES.get(code, CHECKS[code][0])}): {CHECKS[code][1]}")
        return "\n".join(out) + "\n"

    def github_annotations(self, limit=50):
        """Lines GitHub Actions turns into annotations on the run page."""
        level = {"error": "error", "warning": "warning", "notice": "notice"}
        lines = []
        for sev, code, src, msg, line in sorted(self.items, key=lambda i: SEVERITY_ORDER.index(i[0]))[:limit]:
            path = "content/" + src.split("::")[0]
            loc = f"file={path}" + (f",line={line}" if line else "")
            text = f"{src}: {msg}".replace("%", "%25").replace("\r", "").replace("\n", " ")
            lines.append(f"::{level[sev]} {loc},title=metadata {code}::{text}")
        return lines

# =============================================================================
#  Aggregator
# =============================================================================
class MetadataAggregator:
    def __init__(self, dry_run=DRY_RUN):
        self.dry_run = dry_run
        self.report = Report()
        self.pages = []
        self.file_count = 0
        self.content_root = None
        self.allowed = {}
        self.allowed_tags = None
        self.file_index = set()     # vault paths, lower case, without .md for pages
        self.file_stems = set()     # bare file names, lower case, without .md for pages
        self.bodies = {}            # src_rel -> body text
        self.raw_definitions = {}   # src_rel -> {key: value}
        self.used_keys = defaultdict(set)

    # ---------- locating the vault ----------
    def find_content_root(self):
        """The vault. METADATA_AGG_CONTENT_ROOT (a folder containing `content`) still works for testing."""
        root_env = os.environ.get("METADATA_AGG_CONTENT_ROOT")
        if root_env and os.path.isdir(os.path.join(root_env, "content")):
            return pathlib.Path(root_env, "content").resolve()
        return mc.VAULT if mc.VAULT.is_dir() else None

    def build_file_index(self):
        for dirpath, dirnames, filenames in os.walk(self.content_root):
            dirnames[:] = [d for d in dirnames if d not in {".git", "node_modules", ".obsidian", "public"}]
            for fn in filenames:
                rel = os.path.relpath(os.path.join(dirpath, fn), self.content_root).replace("\\", "/")
                if rel.lower().endswith(".md"):
                    self.file_index.add(rel[:-3].lower())
                    self.file_stems.add(fn[:-3].lower())
                self.file_index.add(rel.lower())
                self.file_stems.add(fn.lower())

    def link_exists(self, target):
        t = target.strip().replace("\\", "/").strip("/")
        if not t:
            return True  # [[#Heading]] on the same page
        low = t.lower()
        if low in self.file_index or (low.endswith(".md") and low[:-3] in self.file_index):
            return True
        return low.split("/")[-1] in self.file_stems and "/" not in low

    # ---------- resolving definitions ----------
    def recursive_resolve(self, node, clean_defs, src, field=None):
        """Replace definition keys with their text, recording which keys were used."""
        def resolve(v, key):
            stripped = v.strip("'\" ")
            if stripped in clean_defs:
                self.used_keys[src].add(stripped)
                return clean_defs[stripped]
            return v

        if isinstance(node, dict):
            for k, v in node.items():
                if isinstance(v, str):
                    node[k] = resolve(v, k)
                elif isinstance(v, (dict, list)):
                    self.recursive_resolve(v, clean_defs, src, k)
        elif isinstance(node, list):
            for i, item in enumerate(node):
                if isinstance(item, str):
                    node[i] = resolve(item, field)
                elif isinstance(item, (dict, list)):
                    self.recursive_resolve(item, clean_defs, src, field)

    def find_unresolved(self, node, clean_defs, src, path=""):
        """Report values in definition fields that still look like keys after resolving."""
        lower_defs = {k.lower(): k for k in clean_defs}
        def check(value, field, where):
            if field not in DEFINITION_FIELDS or not looks_like_key(value):
                return
            v = value.strip("'\" ")
            if field == "name" and not ("_" in v or any(c.isdigit() for c in v)):
                return  # names like "Ragno" are real text
            hint = ""
            if v.lower() in lower_defs:
                hint = f" (a definition `{lower_defs[v.lower()]}` exists; keys are case-sensitive)"
            elif clean_defs:
                close = [k for k in clean_defs if k.rstrip("0123456789") == v.rstrip("0123456789")]
                if close:
                    hint = f" (defined keys like it: {', '.join('`'+c+'`' for c in sorted(close)[:5])})"
            self.report.add("unresolved-key", src, f"`{where}` is `{v}`, but there's no `{v}:` definition{hint}.")

        def walk(n, field, where):
            if isinstance(n, dict):
                for k, v in n.items():
                    walk(v, k, f"{where}.{k}" if where else k)
            elif isinstance(n, list):
                for i, v in enumerate(n):
                    walk(v, field, f"{where}[{i}]")
            elif isinstance(n, str):
                check(n, field, where)
        walk(node, None, path)

    # ---------- per-node checks ----------
    def check_enums(self, data, src):
        for key in ("type",):
            val = data.get(key)
            if isinstance(val, (list, dict)):
                self.report.add("malformed", src, f"`{key}` should be a single value, not `{val}`.")
            elif val is not None and str(val) not in self.allowed[key]:
                options = ", ".join(f"`{o}`" for o in sorted(self.allowed[key]))
                self.report.add("invalid-value", src, f"`{key}: {val}` isn't allowed. Use one of {options}.")
        for key in ("has", "needs"):
            val = data.get(key)
            if val is None:
                continue
            if not isinstance(val, list):
                self.report.add("malformed", src, f"`{key}` should be a list.")
                continue
            for item in val:
                if str(item) not in self.allowed["has"]:
                    self.report.add("invalid-value", src, f"`{key}` has `{item}`, which isn't one of {', '.join('`'+o+'`' for o in sorted(self.allowed['has']))}.")

    def is_generated_page(self, data, src):
        """Is the page made by a program? (It has an `index:` block, or it's a decade or
        century page: decade pages are written by the decade generator, and century pages
        are made of embedded decade sections.)"""
        path = src.split("::")[0]
        return bool(data.get("index")) or path.startswith(mc.DECADES_DIR_REL + "/") or path.startswith(mc.CENTURIES_DIR_REL + "/")

    def check_status(self, data, src, is_subpage, parent_status):
        """Check the page's `status` block and replace it with a complete one
        ({scope, progress, future}); subpages take missing values from their parent."""
        raw = data.get("status")
        old = isinstance(raw, str) or (not is_subpage and "future" in data) or (is_subpage and "future" in data and not isinstance(raw, dict))
        if old:
            self.report.add("old-status-format", src, "Uses the old one-line `status:`/`future:`. Run Private Programs/migrate_status.py to convert it.")
            block = mc.status_of(data, parent_status)
            data.pop("future", None)
            data["status"] = block
            return
        if raw is None:
            if is_subpage:
                data["status"] = dict(parent_status) if parent_status else mc.status_of({})
                return
            if data.get("type") not in STATUS_TYPES:
                return  # ledgers, private notes etc. don't need one
            self.report.add("missing-key", src, f"`status` is missing; using scope `{mc.STATUS_DEFAULTS['scope']}`, progress `{mc.STATUS_DEFAULTS['progress']}`.")
            data["status"] = mc.status_of({})
            return
        if not isinstance(raw, dict):
            self.report.add("malformed", src, "`status` should be a block of `scope:`, `progress:` and `future:` (indented under `status:`, no dashes).")
            data["status"] = mc.status_of({}, parent_status)
            return
        if not is_subpage:
            for k in ("scope", "progress"):
                if k not in raw and not (k == "progress" and raw.get("scope") == "generated"):
                    self.report.add("missing-key", src, f"`status.{k}` is missing; using `{mc.STATUS_DEFAULTS[k]}`.")
        if raw.get("scope") == "generated" and "progress" not in raw:
            raw = dict(raw, progress="complete")
        for k in ("scope", "progress"):
            v = raw.get(k)
            if v is not None and str(v) not in self.allowed[k]:
                options = ", ".join(f"`{o}`" for o in sorted(self.allowed[k]))
                self.report.add("invalid-value", src, f"`status.{k}: {v}` isn't allowed. Use one of {options}.")
        fut = raw.get("future")
        if fut is not None and not isinstance(fut, list):
            self.report.add("malformed", src, f"`status.future` should be a list, like `future: [{fut}]`.")
        for v in mc.as_future_list(fut):
            if v not in self.allowed["future"]:
                options = ", ".join(f"`{o}`" for o in sorted(self.allowed["future"]))
                self.report.add("invalid-value", src, f"`status.future` has `{v}`, which isn't one of {options}.")
        for k in raw:
            if k not in ("scope", "progress", "future"):
                self.report.add("invalid-value", src, f"`status.{k}` isn't a status key (use scope, progress and future).")
        block = mc.status_of({"status": raw}, parent_status)
        if block["scope"] == "brief" and block["progress"] == "stub":
            self.report.add("status-conflict", src, "`scope: brief` with `progress: stub`: a presentable brief page is `complete`.")
        if not is_subpage:
            actual = self.is_generated_page(data, src)
            if actual and block["scope"] != "generated":
                self.report.add("generated-mismatch", src, f"A program writes this page, so `status.scope` should be `generated` (it's `{block['scope']}`).")
            elif block["scope"] == "generated" and not actual:
                self.report.add("generated-mismatch", src, "`status.scope` is `generated`, but no program writes this page (it has no `index:` block and isn't a decade or century page).")
        data["status"] = block

    def check_tags(self, data, src, is_subpage):
        tags = data.get("tags")
        if tags is None:
            return
        if isinstance(tags, str):
            self.report.add("malformed", src, "`tags` should be a list, not a single string.")
            tags = [tags]
        if not isinstance(tags, list):
            self.report.add("malformed", src, "`tags` should be a list.")
            return
        if not any(str(t).startswith("topic/") for t in tags):
            self.report.add("missing-topic-tag", src, "Add at least one `topic/...` tag.")
        if self.allowed_tags is None:
            return
        for t in tags:
            t = str(t).strip()
            if t not in self.allowed_tags:
                close = difflib.get_close_matches(t, sorted(self.allowed_tags), n=1, cutoff=0.85)
                hint = f" Did you mean `{close[0]}`?" if close else " Add it to Meta/Metadata.md if it's new."
                self.report.add("unknown-tag", src, f"Tag `{t}` isn't documented.{hint}")

    def check_dates(self, data, src, is_template):
        def walk(n, where):
            if isinstance(n, dict):
                for k, v in n.items():
                    w = f"{where}.{k}" if where else k
                    if k.lower() in DATE_FIELDS:
                        _, _, problem = split_date(v)
                        if problem == "empty":
                            if not is_template and not where.startswith("event["):
                                self.report.add("empty-date", src, f"`{w}` is empty.")
                        elif problem:
                            self.report.add("invalid-date", src, f"`{w}` {problem}.")
                    elif isinstance(v, (dict, list)):
                        walk(v, w)
                for a, b in (("start_date", "end_date"), ("birth_date", "death_date")):
                    if a in n and b in n:
                        va, vb = date_sort_value(n[a]), date_sort_value(n[b])
                        if va is not None and vb is not None and vb < va:
                            self.report.add("date-order", src, f"In `{where or 'page'}`, `{b}` {n[b]} is before `{a}` {n[a]}.")
            elif isinstance(n, list):
                for i, v in enumerate(n):
                    walk(v, f"{where}[{i}]")
        walk(data, "")

    def check_blocks(self, data, src, is_subpage, is_template):
        if is_template:
            return
        for i, ev in enumerate(self._as_list(data, "event", src)):
            if not isinstance(ev, dict):
                self.report.add("malformed", src, f"`event[{i}]` should be a set of keys.")
                continue
            if not ev.get("start_date") and not ev.get("start_desc"):
                self.report.add("missing-field", src, f"`event[{i}]` is an empty placeholder (no `start_date` or `start_desc`), so it won't appear anywhere.")
                continue
            if not ev.get("start_date"):
                self.report.add("missing-field", src, f"`event[{i}]` has no `start_date`, so it won't appear on any decade page.")
            if not ev.get("start_desc"):
                self.report.add("missing-field", src, f"`event[{i}]` has no `start_desc`.")
            if ev.get("end_date") and not ev.get("end_desc") and "end_desc" in ev:
                self.report.add("missing-field", src, f"`event[{i}]` has an empty `end_desc`.")
        for i, st in enumerate(self._as_list(data, "star", src)):
            if not isinstance(st, dict):
                self.report.add("malformed", src, f"`star[{i}]` should be a set of keys.")
                continue
            if not st.get("name"):
                self.report.add("missing-field", src, f"`star[{i}]` has no `name`.")
            if st.get("star_type") and st["star_type"] not in STAR_TYPES:
                self.report.add("invalid-value", src, f"`star[{i}].star_type` is `{st['star_type']}`; use {', '.join(sorted(STAR_TYPES))}.")
            orb = st.get("orbital")
            if isinstance(orb, dict):
                if orb.get("center_mode") and orb["center_mode"] not in ORBIT_CENTER_MODES:
                    self.report.add("invalid-value", src, f"`star[{i}].orbital.center_mode` is `{orb['center_mode']}`; use coordinates or explicit.")
                if orb.get("center_mode") == "explicit" and not orb.get("center"):
                    self.report.add("missing-field", src, f"`star[{i}].orbital` uses center_mode explicit but has no `center`.")
                period = orb.get("period")
                if period is not None and (not isinstance(period, (int, float)) or period <= 0):
                    self.report.add("invalid-value", src, f"`star[{i}].orbital.period` should be a positive number of days.")
            for kind, who in (("publications", "publishers"), ("translations", "translators")):
                for j, entry in enumerate(st.get(kind) or []):
                    if isinstance(entry, dict) and not entry.get("date") and entry.get("date") != 0:
                        pass  # empty dates are reported by check_dates
                    if isinstance(entry, dict) and who in entry and not isinstance(entry[who], list):
                        self.report.add("malformed", src, f"`star[{i}].{kind}[{j}].{who}` should be a list.")
        people = self._as_list(data, "person", src)
        for i, p in enumerate(people):
            if not isinstance(p, dict):
                self.report.add("malformed", src, f"`person[{i}]` should be a set of keys.")
                continue
            if not p.get("name"):
                self.report.add("missing-field", src, f"`person[{i}]` has no `name`.")
            for key in ("parents", "children"):
                if key in p and not isinstance(p[key], list):
                    self.report.add("malformed", src, f"`person[{i}].{key}` should be a list.")
        if len(people) == 1 and isinstance(people[0], dict) and people[0].get("name"):
            name = str(people[0]["name"]).strip()
            title = str(data.get("title", "")).strip()
            aliases = {str(a).strip().lower() for a in (data.get("aliases") or []) if a}
            if title and name.lower() != title.lower() and name.lower() not in aliases:
                if is_subpage:
                    self.report.add("person-name", src, f"Subpage \"{title}\" has a person block named \"{name}\".")
                else:
                    self.report.add("person-name-page", src, f"Page \"{title}\" has a single person block named \"{name}\".")

    def _as_list(self, data, key, src):
        val = data.get(key)
        if val is None:
            return []
        if not isinstance(val, list):
            self.report.add("malformed", src, f"`{key}` should be a list (start each entry with `- `).")
            return []
        return val

    def check_featured(self, data, src):
        fd = data.get("featured_data")
        has = data.get("has") if isinstance(data.get("has"), list) else []
        if "featured_data" in has and not fd:
            self.report.add("has-mismatch", src, "`has` lists `featured_data` but there's no `featured_data` block.")
        if not isinstance(fd, dict):
            if fd is not None:
                self.report.add("malformed", src, "`featured_data` should be a set of keys.")
            return
        facts = fd.get("fun_facts")
        if facts is not None and not isinstance(facts, list):
            self.report.add("malformed", src, "`featured_data.fun_facts` should be a list.")
            facts = [facts]
        for i, f in enumerate(facts or []):
            text = str(f).strip()
            if looks_like_key(text):
                continue  # reported as unresolved-key
            if not text.startswith("...") or "?" not in text:
                self.report.add("fun-fact-format", src, f"`fun_facts[{i}]` should read \"... that ...?\": {text[:70]}")
        desc = fd.get("featured_desc")
        if isinstance(desc, str) and desc.strip() and not looks_like_key(desc) and not desc.strip().startswith("**[["):
            self.report.add("featured-desc-format", src, "`featured_desc` should start with a bold link to the page, like **[[...]]**.")

    def check_links(self, data, src):
        def walk(n, where):
            if isinstance(n, dict):
                for k, v in n.items():
                    if k in ("original",):
                        continue
                    walk(v, f"{where}.{k}" if where else k)
            elif isinstance(n, list):
                for i, v in enumerate(n):
                    walk(v, f"{where}[{i}]")
            elif isinstance(n, str):
                for m in WIKILINK_RE.finditer(n):
                    if not self.link_exists(m.group(1)):
                        self.report.add("broken-link", src, f"`{where}` links to `{m.group(1).strip()}`, which doesn't exist.")
        walk(data, "")

    def check_index_blocks(self, data, src, body):
        blocks = self._as_list(data, "index", src)
        if not blocks:
            return
        headings = {h.group(2).strip() for h in HEADING_RE.finditer(body)}
        for i, b in enumerate(blocks):
            if not isinstance(b, dict):
                self.report.add("malformed", src, f"`index[{i}]` should be a set of keys.")
                continue
            hn = b.get("header_name")
            if not hn:
                self.report.add("missing-field", src, f"`index[{i}]` has no `header_name`.")
            elif str(hn).strip() not in headings:
                self.report.add("index-header", src, f"`index[{i}].header_name` is \"{hn}\", but the page has no heading with that text, so the list can't be written.")
            if not b.get("included_data") and not b.get("excluded_data"):
                self.report.add("missing-field", src, f"`index[{i}]` has neither `included_data` nor `excluded_data`.")
            for j, s in enumerate(b.get("sort") or []):
                if not isinstance(s, dict):
                    continue
                if not s.get("by"):
                    self.report.add("missing-field", src, f"`index[{i}].sort[{j}]` has no `by`.")
                if s.get("method") and s["method"] not in self.allowed["sort_method"]:
                    self.report.add("invalid-value", src, f"`index[{i}].sort[{j}].method` is `{s['method']}`.")
                sh = s.get("subheaders")
                if isinstance(sh, dict) and sh.get("method"):
                    m = str(sh["method"])
                    ok = m in self.allowed["subheader_method"] or (re.fullmatch(r"floor_\d+", m) and "floor_x" in self.allowed["subheader_method"])
                    if not ok:
                        self.report.add("invalid-value", src, f"`index[{i}].sort[{j}].subheaders.method` is `{m}`.")

    def check_callouts(self, data, src, body):
        tags = data.get("tags") or []
        if isinstance(tags, list) and CALLOUT_CHECK_SKIP_TAGS & {str(t) for t in tags}:
            return
        text = CODE_FENCE_RE.sub("", COMMENT_RE.sub("", body))
        found = {m.group(1).strip() for line in text.splitlines() if line.lstrip().startswith(">")
                 for m in CALLOUT_LINK_RE.finditer(line)}
        for old in sorted(found & OLD_CALLOUTS):
            self.report.add("callout-mismatch", src, f"The \"{old}\" callout is from before the status rework (run migrate_status.py, or swap it for the new one in Meta/Callouts).")
        st = data.get("status") if isinstance(data.get("status"), dict) else None
        checks = [("type", str(data.get("type", "")), TYPE_CALLOUTS)]
        if st:
            if src != mc.HOME_PAGE_REL:   # the home page's top belongs to the featured block
                checks.append(("status.progress", st.get("progress", ""), PROGRESS_CALLOUTS))
            checks.append(("status.scope", st.get("scope", ""), SCOPE_CALLOUTS))
        for label, val, mapping in checks:
            expected = mapping.get(val)
            present = found & set(mapping.values())
            if expected and expected not in found:
                self.report.add("callout-mismatch", src, f"`{label}: {val}` but the page has no \"{expected}\" callout.")
            for other in sorted(present - ({expected} if expected else set())):
                self.report.add("callout-mismatch", src, f"The page has a \"{other}\" callout but `{label}` is `{val}`.")
        if st:
            wanted = {FUTURE_CALLOUTS[f] for f in st.get("future", []) if f in FUTURE_CALLOUTS}
            present = found & set(FUTURE_CALLOUTS.values())
            for f in sorted(wanted - present):
                self.report.add("callout-mismatch", src, f"`status.future` includes `{next(k for k, v in FUTURE_CALLOUTS.items() if v == f)}` but the page has no \"{f}\" callout.")
            for f in sorted(present - wanted):
                self.report.add("callout-mismatch", src, f"The page has a \"{f}\" callout but `status.future` doesn't include `{next(k for k, v in FUTURE_CALLOUTS.items() if v == f)}`.")

    def check_ledger(self, data, src):
        if data.get("type") != "ledger":
            return
        ld = data.get("ledger_data")
        if not isinstance(ld, dict):
            self.report.add("missing-field", src, "Lore Ledger has no `ledger_data` block (week and year).")
            ld = {}
        fm = LEDGER_FILE_RE.search(src)
        tm = LEDGER_TITLE_RE.search(str(data.get("title", "")))
        parts = []
        if fm:
            parts.append(("file name", int(fm.group(1)), int(fm.group(2))))
        if tm:
            parts.append(("title", int(tm.group(1)), 2000 + int(tm.group(2))))
        elif data.get("title"):
            self.report.add("ledger-mismatch", src, f"Title \"{data.get('title')}\" isn't in the form \"Lore Ledger WW.YY\".")
        if "week" in ld or "year" in ld:
            parts.append(("ledger_data", ld.get("week"), ld.get("year")))
        if len({(w, y) for _, w, y in parts}) > 1:
            desc = "; ".join(f"{n} says week {w}, {y}" for n, w, y in parts)
            self.report.add("ledger-mismatch", src, f"These disagree: {desc}.")

    # ---------- processing ----------
    def process_metadata_node(self, data, definitions, src_id, is_subpage=False, parent=None, rel_path="", check=True):
        """Fill defaults, check, resolve definitions, normalise dates."""
        if not check:
            saved = self.report
            self.report = Report()  # throw away follow-on issues from an unreadable page
            try:
                return self.process_metadata_node(data, definitions, src_id, is_subpage, parent, rel_path, True)
            finally:
                self.report = saved
        is_template = (data.get("type") or (parent or {}).get("type")) == "template"

        # Defaults. Subpages inherit their type and status block from their parent page.
        if is_subpage:
            data.setdefault("type", parent.get("type", DEFAULT_VALUES["type"]))
            if "title" not in data:
                self.report.add("missing-key", src_id, "Subpage has no `title`.")
        else:
            for k in REQUIRED_KEYS:
                if k not in data:
                    if k in DEFAULT_VALUES:
                        self.report.add("missing-key", src_id, f"`{k}` is missing; using `{DEFAULT_VALUES[k]}`.")
                    else:
                        self.report.add("missing-key", src_id, f"`{k}` is missing.")
            for k, v in DEFAULT_VALUES.items():
                data.setdefault(k, v)

        if "title" not in data:
            data["title"] = os.path.splitext(os.path.basename(rel_path))[0]

        self.check_enums(data, src_id)
        self.check_status(data, src_id, is_subpage, (parent or {}).get("status") if is_subpage else None)
        self.check_tags(data, src_id, is_subpage)
        self.check_dates({k: v for k, v in data.items() if k != "subpage"}, src_id, is_template)

        # Resolve string values recursively via the comment block.
        clean_defs = {str(dk).strip("'\" "): str(dv).strip("'\" ") for dk, dv in definitions.items()}
        resolve_target = {k: v for k, v in data.items() if k != "subpage"}
        self.recursive_resolve(resolve_target, clean_defs, rel_path)
        data.update(resolve_target)
        if not is_template:
            self.find_unresolved({k: v for k, v in data.items() if k not in ("subpage", "aliases", "tags", "title")}, clean_defs, src_id)

        # Normalise dates.
        def resolve_dates_recursive(node):
            if isinstance(node, dict):
                for k in list(node.keys()):
                    if isinstance(node[k], (dict, list)) and k.lower() not in DATE_FIELDS:
                        resolve_dates_recursive(node[k])
                    if k.lower() in DATE_FIELDS:
                        norm = parse_mysenvar_date(node[k])
                        if norm:
                            node[k] = norm
            elif isinstance(node, list):
                for item in node:
                    resolve_dates_recursive(item)
        for k in list(data.keys()):
            if k == "subpage":
                continue
            if k.lower() in DATE_FIELDS:
                norm = parse_mysenvar_date(data[k])
                if norm:
                    data[k] = norm
            elif isinstance(data[k], (dict, list)):
                resolve_dates_recursive(data[k])

        if not is_template:
            self.check_blocks(data, src_id, is_subpage, is_template)
            self.check_featured(data, src_id)
            self.check_links({k: v for k, v in data.items() if k not in ("subpage", "link")}, src_id)

        # Ensure a link exists.
        if "link" not in data:
            title = data["title"]
            if is_subpage:
                slug = title.lower().replace(" ", "-")
                parent_link = parent.get("link") if parent else ""
                parent_base = parent_link.split("|")[0].strip("[]") if parent_link else ""
                data["link"] = f"[[{parent_base}#{slug}|{title}]]"
            else:
                normalized_path = os.path.splitext(rel_path)[0].replace("\\", "/")
                data["link"] = f"[[{normalized_path}|{title}]]"
        elif not is_template and isinstance(data["link"], str):
            self.check_links({"link": data["link"]}, src_id)
        return data

    def process_file(self, full_path, rel_path):
        try:
            with open(full_path, "r", encoding="utf-8") as f:
                content = f.read()
        except (OSError, UnicodeDecodeError) as e:
            self.report.add("read-error", rel_path, f"Couldn't read the file: {e}")
            return

        fm_dict, body_text = {}, content
        readable = True
        m = FRONTMATTER_RE.match(content)
        if not m:
            self.report.add("no-frontmatter", rel_path, "Add a --- front matter block at the very top of the page. Nothing else on this page was checked.")
            readable = False
        else:
            fm_text, body_text = m.group(1), content[m.end():]
            if yaml is not None:
                try:
                    fm_dict = yaml.safe_load(fm_text) or {}
                except yaml.YAMLError as e:
                    mark = getattr(e, "problem_mark", None)
                    line = mark.line + 2 if mark is not None else None
                    problem = getattr(e, "problem", None) or str(e).splitlines()[0]
                    if "\t" in fm_text:
                        problem += " (the front matter contains tab characters; YAML needs spaces for indenting)"
                    self.report.add("yaml-error", rel_path, f"YAML error: {problem}. The basic parser was used instead, so lists and nested blocks on this page were lost. Nothing else on this page was checked.", line)
                    fm_dict = fallback_parse_yaml(fm_text)
                    readable = False
            else:
                fm_dict = fallback_parse_yaml(fm_text)
            if not isinstance(fm_dict, dict):
                self.report.add("yaml-error", rel_path, "The front matter isn't a set of `key: value` pairs.")
                fm_dict = {}

        definitions = {}
        for cm in COMMENT_RE.finditer(body_text):
            for line in cm.group(1).strip().splitlines():
                if ":" in line:
                    k, v = line.split(":", 1)
                    definitions[k.strip()] = v.strip()

        clean_rel_path = rel_path.replace("\\", "/")
        subpages_raw = fm_dict.get("subpage")
        fm_dict = self.process_metadata_node(fm_dict, definitions, clean_rel_path, rel_path=clean_rel_path, check=readable)
        self.pages.append({"src_rel": clean_rel_path, "definitions": definitions, "metadata": fm_dict})
        self.bodies[clean_rel_path] = body_text
        self.raw_definitions[clean_rel_path] = definitions

        if not readable:
            return
        if fm_dict.get("type") == "private" and not clean_rel_path.startswith("Private/"):
            self.report.add("private-published", clean_rel_path, "Type is `private` but the page is outside Private/, so it will be published.")
        if fm_dict.get("type") == "template" and fm_dict.get("draft") is not True:
            self.report.add("draft-template", clean_rel_path, "Add `draft: true` so the template isn't published.")
        if fm_dict.get("type") != "template":
            self.check_index_blocks(fm_dict, clean_rel_path, body_text)
            self.check_callouts(fm_dict, clean_rel_path, body_text)
        self.check_ledger(fm_dict, clean_rel_path)

        if subpages_raw is not None and not isinstance(subpages_raw, list):
            self.report.add("malformed", clean_rel_path, "`subpage` should be a list (start each subpage with `- `).")
        elif isinstance(subpages_raw, list):
            for i, sub_fm in enumerate(subpages_raw):
                sub_src = f"{clean_rel_path}::subpage[{i}]"
                if not isinstance(sub_fm, dict):
                    self.report.add("malformed", clean_rel_path, f"`subpage[{i}]` should be a set of keys.")
                    continue
                label = f"{clean_rel_path}::subpage[{i}] \"{sub_fm.get('title', '?')}\""
                processed = self.process_metadata_node(sub_fm, definitions, label, is_subpage=True,
                                                       parent=fm_dict, rel_path=clean_rel_path)
                self.pages.append({"src_rel": sub_src, "definitions": definitions,
                                   "metadata": processed, "parent": clean_rel_path})

    # ---------- whole-vault checks ----------
    def check_duplicates(self):
        titles = defaultdict(list)
        aliases = defaultdict(list)
        for p in self.pages:
            if "::" in p["src_rel"]:
                continue
            md = p["metadata"]
            if md.get("type") == "template":
                continue
            t = str(md.get("title", "")).strip().lower()
            if t:
                titles[t].append(p["src_rel"])
            for a in md.get("aliases") or []:
                if a:
                    aliases[str(a).strip().lower()].append(p["src_rel"])
        for t, srcs in titles.items():
            if len(srcs) > 1:
                for s in srcs:
                    others = ", ".join(o for o in srcs if o != s)
                    self.report.add("duplicate-title", s, f"Title \"{t}\" is also used by {others}.")
        for a, srcs in aliases.items():
            uniq = sorted(set(srcs))
            if len(uniq) > 1:
                for s in uniq:
                    others = ", ".join(o for o in uniq if o != s)
                    self.report.add("duplicate-alias", s, f"Alias \"{a}\" is also an alias on {others}.")
            if a in titles:
                for s in uniq:
                    owners = [o for o in titles[a] if o != s]
                    if owners:
                        self.report.add("duplicate-alias", s, f"Alias \"{a}\" is the title of {', '.join(owners)}.")

    def check_unused_definitions(self):
        for src, defs in self.raw_definitions.items():
            page = next((p for p in self.pages if p["src_rel"] == src), None)
            if page and page["metadata"].get("type") == "template":
                continue
            tags = page["metadata"].get("tags") if page else []
            if isinstance(tags, list) and CALLOUT_CHECK_SKIP_TAGS & {str(t) for t in tags}:
                continue
            for k in defs:
                key = k.strip("'\" ")
                if key and key not in self.used_keys[src]:
                    self.report.add("unused-definition", src, f"Definition `{key}` isn't used by any metadata on the page.")

    # ---------- run ----------
    def run(self):
        self.content_root = self.find_content_root()
        if self.content_root is None:
            print("Error: Could not find the 'content' folder (set METADATA_AGG_CONTENT_ROOT to the folder that contains it).")
            sys.exit(1)
        print(f"Aggregating metadata from: {self.content_root}")

        if yaml is None:
            self.report.add("pyyaml-missing", "(setup)", "PyYAML isn't installed; run `pip install pyyaml`. Nested metadata was not read.")
        self.allowed, self.allowed_tags = load_allowed_values(self.content_root, self.report)
        self.build_file_index()

        for dirpath, dirnames, filenames in os.walk(self.content_root):
            dirnames[:] = sorted(d for d in dirnames if d not in EXCLUDE_DIRS)
            for filename in sorted(filenames):
                if filename.lower().endswith(".md"):
                    self.file_count += 1
                    full_path = os.path.join(dirpath, filename)
                    rel_path = os.path.relpath(full_path, self.content_root)
                    try:
                        self.process_file(full_path, rel_path)
                    except Exception as e:  # keep going; report what broke
                        self.report.add("read-error", rel_path.replace("\\", "/"), f"Unexpected problem while reading this page: {type(e).__name__}: {e}")

        self.check_duplicates()
        self.check_unused_definitions()

        counts = self.report.counts()
        output_dir = self.content_root / OUTPUT_DIR_REL
        json_payload = {
            "meta": {
                "total_markdown_files": self.file_count,
                "pages_extracted": len(self.pages),
                "warnings": len(self.report.items),
                "issues": counts,
                "working_directory": os.getcwd(),
            },
            "pages": self.pages,
            "issues": [
                {"severity": s, "check": c, "source": src, "message": msg, **({"line": ln} if ln else {})}
                for s, c, src, msg, ln in self.report.items
            ],
        }

        summary = f"{len(self.pages)} entries from {self.file_count} files: {counts['error']} errors, {counts['warning']} warnings, {counts['notice']} notices."
        if self.dry_run:
            print("DRY RUN - nothing written.")
            print(self.report.render(include_notices=not ARGS.quiet))
        else:
            os.makedirs(output_dir, exist_ok=True)
            with open(output_dir / "extracted_metadata.json", "w", encoding="utf-8") as f:
                json.dump(json_payload, f, indent=4, ensure_ascii=False)
            with open(output_dir / "metadata_warnings.txt", "w", encoding="utf-8") as f:
                f.write(self.report.render())
            print(f"SUCCESS: Metadata written to {output_dir / 'extracted_metadata.json'}")
            print(f"Report written to {output_dir / 'metadata_warnings.txt'}")
        print(summary)
        if os.environ.get("GITHUB_ACTIONS") == "true":
            for line in self.report.github_annotations():
                print(line)
        if ARGS.strict and counts["error"]:
            sys.exit(1)


def parse_args():
    p = argparse.ArgumentParser(description="Aggregate and check the Encyclopedia's page metadata.")
    p.add_argument("--dry-run", action="store_true", help="print the report and write nothing")
    p.add_argument("--strict", action="store_true", help="exit with code 1 if there are errors")
    p.add_argument("--quiet", action="store_true", help="leave notices out of the console report")
    return p.parse_args()


ARGS = argparse.Namespace(dry_run=False, strict=False, quiet=False)

if __name__ == "__main__":
    ARGS = parse_args()
    MetadataAggregator(dry_run=ARGS.dry_run or DRY_RUN).run()
